function idlm_aud_http_lead($owner): int { global $wpdb;$now=current_time('mysql');$wpdb->insert($wpdb->prefix.'idlm_leads',array('first_name'=>'Synthetic audience','email'=>'audience-http@example.test','phone'=>'919999900070','stage'=>'Qualified','assigned_rep_id'=>$owner,'created_at'=>$now,'updated_at'=>$now));return (int)$wpdb->insert_id; }
