function idlm_aud_http_run($actor='admin'): array { global $sessions; return idlm_http_request('/wp-admin/admin-ajax.php',array('action'=>'idlm_trigger_manual_audience_sync','nonce'=>$sessions[$actor]['admin']),$actor); }
